import math

def M_n(n):
    if n <= 1:
        return 0.0
    # M_n = 4/n * [ (n-1) + (n-1)^(2/3) ]
    return (4.0 / n) * ((n - 1) + (n - 1)**(2.0/3.0))

# Check values up to n=15
n_values = range(2, 16)
results = {}
for n in n_values:
    results[n] = M_n(n)

print("n values:", list(results.keys()))
print("Corresponding M_n values:", [results[n] for n in n_values])
print("Maximum found:", max(results.values()))
